let books be csv_parse(read_file("./cases/02-llm-written-analytics/data/books.csv"), {"types": {"price": "float"}})
let groups be summarize(books, "category", {"n": count(), "mean_price": mean_of("price")})
let filtered be where(groups, (g) => g.n >= 5)
let sorted be sort_by(filtered, (g) => g.mean_price, desc = true)
let top be sorted[0]
print(`category: {top.category}`)
print(`books: {top.n}`)
print(`avg price: {round_to(top.mean_price, 2)}`)

let path be "./cases/02-llm-written-analytics/data/weather_summary.csv"
let raw be csv_parse(read_file(path), {"types": {"temp_mean": "float", "temp_min": "float", "temp_max": "float", "rain_total_mm": "float", "wind_p95": "float", "missing_hours": "int"}})
let sorted be sort_by(raw, (r) => r.rain_total_mm, desc = true)
let top3 be slice(sorted, 0, 3)
each r in top3
    print(`{r.city}: rain={round_to(r.rain_total_mm, 1)} mm, mean temp={round_to(r.temp_mean, 2)} °C`)
let avg be mean(apply((r) => r.temp_mean, top3))
print(`Mean temperature of top 3 rainiest cities: {round_to(avg, 2)} °C`)

let raw be csv_parse(read_file("./cases/02-llm-written-analytics/data/steam_regional_prices.csv"), {"types": {"index": "float"}})
let clean be drop_missing(raw, "index")
let grouped be summarize(clean, "country", {"median_index": median_of("index")})
let sorted be sort_by(grouped, (r) => r.median_index)
let lowest be sorted[0]
print(`Country with lowest median price index relative to US: {lowest.country}, median index: {round_to(lowest.median_index, 2)}`)

let rows be csv_parse(read_file("./cases/02-llm-written-analytics/data/game_prices.csv"), {"types": {"discount_pct": "float", "cheapest": "float", "list_price": "float"}})

let stats be summarize(rows, "cheapest_store", {"n": count(), "mean_disc": mean_of("discount_pct")})

let ranked be sort_by(stats, (r) => r.n, desc = true)

let top be ranked[0]

print(`Store appearing most often as cheapest: {top.cheapest_store}`)
print(`Times it was cheapest: {top.n}`)
print(`Average discount on those games: {round_to(top.mean_disc, 2)}%`)
print("Top 5 by frequency:")
each r in slice(ranked, 0, 5)
    print(`  {r.cheapest_store}: n={r.n}, avg_discount={round_to(r.mean_disc, 2)}%`)

let rows be parquet_read(read_file_bytes("./cases/02-llm-written-analytics/data/taxi_hour_borough.parquet"))
let bkn be where(rows, (r) => r.borough == "Brooklyn")
let ranked be sort_by(bkn, (r) => r.mph)
let slowest be ranked[0]
print(`Brooklyn: {length(bkn)} hourly rows analyzed`)
print(`slowest hour: {slowest.hour} at {round_to(slowest.mph, 2)} mph`)
print(`tip_pct at that hour: {round_to(slowest.tip_pct, 2)}%`)
print(`trips in that hour: {slowest.trips}`)

let monthly be parquet_read(read_file_bytes("./cases/02-llm-written-analytics/data/taxi_monthly.parquet"))
let rows be apply((r) => {"month": r.month, "rpm": r.revenue / r.trips}, monthly)
let sorted be sort_by(rows, (r) => r.rpm, desc = true)
let best be sorted[0]
print(`Month with highest average revenue per trip: {best.month}`)
print(`Average revenue per trip: {round_to(best.rpm, 4)}`)
each r in rows
    print(`  {r.month}: {round_to(r.rpm, 4)}`)

let trades be jsonl_decode(read_file("./cases/02-llm-written-analytics/data/trades.jsonl"))

let btc be where(trades, (r) => r.pair == "BTC")

let with_notional be apply((r) => merge(r, {"notional": r.price * r.size}), btc)

let grouped be summarize(with_notional, "exchange", {"notional": sum_of("notional"), "volume": sum_of("size"), "trades": count()})

let priced be apply((r) => merge(r, {"vwap": r.notional / r.volume}), grouped)

each r in priced
    print(`{r.exchange}: trades={r.trades} volume={round_to(r.volume, 4)} vwap={round_to(r.vwap, 6)}`)

let sorted be sort_by(priced, (r) => r.vwap)
let low be sorted[0]
let high be sorted[-1]
let mid be (low.vwap + high.vwap) / 2
let diff be high.vwap - low.vwap
let bps be round_to(diff / mid * 10000, 2)

print(`high: {high.exchange} {round_to(high.vwap, 6)}`)
print(`low: {low.exchange} {round_to(low.vwap, 6)}`)
print(`abs difference: {round_to(diff, 6)} USD`)
print(`difference in basis points (relative to midpoint): {bps} bps`)

let rows be csv_parse(read_file("./cases/02-llm-written-analytics/data/teacher_labels.csv"))
let matched be apply((r) => merge(r, {"match": when r.teacher == r.truth then 1 otherwise 0}), rows)
let grp be summarize(matched, "source", {"n": count(), "matches": sum_of("match"), "mean": mean_of("match")})
let out be sort_by(grp, (r) => r.source)
each r in out
    print(`{r.source}: {r.matches}/{r.n} = {round_to(r.mean * 100, 2)}%`)
print(`overall: {sum(collect(matched, "match"))}/{length(matched)} = {round_to(mean(collect(matched, "match")) * 100, 2)}%`)
